"""OpenAPI schema validation and Schemathesis contract conformance test.

Verifies:
1. Complete OpenAPI 3.1 schema generation from FastAPI application.
2. All endpoints declare required responses and valid path parameters.
3. Schemathesis ASGI contract tests against generated API definitions.
"""

from __future__ import annotations

import pytest

from app.main import app


def test_openapi_specification_structural_validity() -> None:
    """Validates structural integrity of the OpenAPI specification generated by FastAPI."""
    openapi_spec = app.openapi()

    assert openapi_spec is not None
    assert "openapi" in openapi_spec
    assert openapi_spec["openapi"].startswith("3.")
    assert "info" in openapi_spec
    assert openapi_spec["info"]["title"]
    assert "paths" in openapi_spec
    assert len(openapi_spec["paths"]) > 0

    # Inspect all registered API operations
    for path, path_item in openapi_spec["paths"].items():
        for method, operation in path_item.items():
            if method.lower() in ("get", "post", "put", "delete", "patch"):
                assert (
                    "responses" in operation
                ), f"Operation {method.upper()} {path} missing 'responses' declaration."
                assert (
                    len(operation["responses"]) > 0
                ), f"Operation {method.upper()} {path} has empty 'responses'."


def test_schemathesis_schema_loader() -> None:
    """Tests loading the OpenAPI schema via Schemathesis ASGI loader."""
    try:
        import schemathesis

        schema = schemathesis.from_asgi("/openapi.json", app)
        assert schema is not None
        assert len(list(schema.get_all_operations())) > 0
    except ImportError:
        pytest.skip("schemathesis is not installed in the current test runner.")
